from pydantic import BaseModel, Field
from typing import Optional, List


class CompanyROEDataPoint(BaseModel):
    """A single company's weighted average return on net assets from one document."""
    company_name: Optional[str] = Field(
        description="The full company name as reported in the document"
    )
    stock_code: Optional[str] = Field(
        description="The stock/security code (e.g., '000006')"
    )
    stock_short_name: Optional[str] = Field(
        description="The stock abbreviation or short name"
    )
    roe_percentage: Optional[float] = Field(
        description="Weighted average return on net assets as a percentage value for Q1 2025"
    )
    reporting_period: Optional[str] = Field(
        description="The reporting period (e.g., '2025-Q1', '2025年第一季度')"
    )
    document_index: Optional[int] = Field(
        description="Document index for reference and potential deduplication"
    )


class Parse(BaseModel):
    """Aggregates all company ROE data points from the collection of documents."""
    company_roe_data_points: List[CompanyROEDataPoint]
